import{_ as n,C as l,o as d,c,a2 as t,E as p,w as r,j as e,a as s}from"./chunks/framework.C2TvIV46.js";const v=JSON.parse('{"title":"ベースファイル","description":"","frontmatter":{},"headers":[],"relativePath":"ja/language/base-files.md","filePath":"ja/language/base-files.md"}'),i={name:"ja/language/base-files.md"};function g(m,a,u,b,h,_){const o=l("DocsBlock");return d(),c("div",null,[a[1]||(a[1]=t('<h1 id="ベースファイル" tabindex="-1">ベースファイル <a class="header-anchor" href="#ベースファイル" aria-label="Permalink to &quot;ベースファイル&quot;">​</a></h1><p>一部の Megalo スクリプトは、<code>base</code> ディレクティブでコンパイル済みの親バリアントから継承します。これが Bungie の <strong>バリアントファミリー</strong> の作り方です — 1 本の完全なゲームタイプスクリプトがベースになり、短い派生スクリプトがメタデータ、チーム、オプションだけを再調整します。</p><h2 id="構文" tabindex="-1">構文 <a class="header-anchor" href="#構文" aria-label="Permalink to &quot;構文&quot;">​</a></h2><p>派生スクリプトは、コンパイル済み <code>.mglo</code> ファイルを指す 1 行の <code>base</code> で始まります。</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">base</span><span class="megalo-text"> </span><span class="megalo-string">&quot;ctf.mglo&quot;</span></span></code></pre></div><p><code>.mglo</code> 拡張子はコンパイル済み Megalo バリアントを指し、ソースの <code>.txt</code> ではありません。エディタはコンパイル時にベースを解決し、派生スクリプトの要素を上にマージします。</p><p>ベースファイルはコンパイルの <strong>出力フォルダ</strong> — MegaloEdit.exe では <code>maps/megalo</code> — から読みます。参照する派生バリアントをビルドする前に、親スクリプトをコンパイルして <code>.mglo</code> を用意してください。</p>',7)),p(o,{type:"warning",title:"同じ megalo バージョン"},{default:r(()=>[...a[0]||(a[0]=[e("p",null,[s("派生スクリプトとそのベース "),e("code",null,".mglo"),s(" は "),e("strong",null,"同じ megalo エンコーディングバージョン"),s(" を対象にしなければなりません。ビルドの混在（たとえば TU1 のベースと MCC 専用の派生、または異なる "),e("a",{href:"/MegaloEvolved/beta/docs/ja/versions/"},"Megalo バージョン"),s(" のベース）はサポートされません — ベースと派生を同じ Reach ビルド向けにコンパイルしてください。")],-1)])]),_:1}),a[2]||(a[2]=t(`<h2 id="何が継承されるか" tabindex="-1">何が継承されるか <a class="header-anchor" href="#何が継承されるか" aria-label="Permalink to &quot;何が継承されるか&quot;">​</a></h2><p>ベースファイルは <strong>コンパイル済みスクリプト全体</strong> を派生バリアントに寄与します。</p><ul><li>すべてのトリガー、条件、アクション</li><li>すべての変数宣言と初期値</li><li>HUD ウィジェット、マップオブジェクトフィルタ、統計</li><li>ロードアウト定義とリクジションパレット</li></ul><p>派生スクリプトはトップレベル要素の <strong>制限された部分集合</strong> だけを再指定します。派生ファイルで宣言できるもの:</p><table tabindex="0"><thead><tr><th>要素</th><th>用途</th></tr></thead><tbody><tr><td><code>engine_data</code></td><td>ゲームタイプ名、説明、アイコン、カテゴリの上書き</td></tr><tr><td><code>teams</code></td><td>チームモデル、色、デザイネータの再調整</td></tr><tr><td><code>game_options</code></td><td>組み込みオプションの上書き、カスタムオプションの追加／ロック</td></tr><tr><td><code>constants</code></td><td>定数の追加または置換</td></tr><tr><td><code>string_table</code> / <code>include</code></td><td>ローカライズ文字列の追加</td></tr><tr><td><code>loadout</code> / <code>loadout_palette</code></td><td>ロードアウト定義の上書き</td></tr><tr><td><code>map_permissions</code></td><td>Forge 配置ルールの変更</td></tr><tr><td><code>player_rating</code></td><td>レーティングパラメータの上書き</td></tr></tbody></table><p>派生ファイルでは次を <strong>追加できません</strong>:</p><ul><li><code>variables</code></li><li><code>trigger</code></li><li><code>hud_widgets</code></li><li><code>map_object</code></li><li><code>requisition_palette</code></li><li><code>game_stats</code></li></ul><p>ゲームロジックを変えるには、ベーススクリプトを編集するか、<code>base</code> 行なしの完全な新規スクリプトを作ってください。</p><h2 id="オプションの再調整" tabindex="-1">オプションの再調整 <a class="header-anchor" href="#オプションの再調整" aria-label="Permalink to &quot;オプションの再調整&quot;">​</a></h2><p>派生スクリプトは同じ <code>game_options</code> 要素で継承したゲームオプションを上書きします。</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">base</span><span class="megalo-text"> </span><span class="megalo-string">&quot;headhunter.mglo&quot;</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-keyword">engine_data</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-parameter">name</span><span class="megalo-text"> team_headhunter_title</span></span>
<span class="line"><span class="megalo-keyword">end</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-keyword">game_options</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">override</span><span class="megalo-text"> </span><span class="megalo-variable">teams_enabled</span><span class="megalo-text"> </span><span class="megalo-number">1</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">override</span><span class="megalo-text"> </span><span class="megalo-variable">score_to_win_round</span><span class="megalo-text"> </span><span class="megalo-number">50</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><p>派生スクリプトでよくあるパターン:</p><ul><li><strong><code>override</code></strong> — 組み込みエンジンオプションを新しいデフォルトに設定</li><li><strong><code>lock override</code></strong> — デフォルトを設定し、ロビーからの変更を禁止</li><li><strong><code>option &quot;Name&quot; value</code></strong> — カスタムオプションを新しいデフォルトで再宣言（一部の派生で使われる短縮形）</li></ul><h2 id="実例" tabindex="-1">実例 <a class="header-anchor" href="#実例" aria-label="Permalink to &quot;実例&quot;">​</a></h2><p>Bungie は多くのバリアントファミリーを出荷しました。各ベース <code>.mglo</code> に複数の派生 <code>.txt</code> があります。</p><table tabindex="0"><thead><tr><th>ベース</th><th>派生バリアント</th></tr></thead><tbody><tr><td><code>ctf.mglo</code></td><td><code>ctf_1flag.txt</code>、<code>ctf_multiteam.txt</code>、<code>ctf_neutralflag.txt</code></td></tr><tr><td><code>headhunter.mglo</code></td><td><code>headhunter_team.txt</code>、<code>headhunter_pro.txt</code>、<code>headhunter_pro_team.txt</code></td></tr><tr><td><code>assault.mglo</code></td><td><code>assault_one_bomb.txt</code>、<code>assault_neutral_bomb.txt</code>、<code>grifball.txt</code></td></tr><tr><td><code>koth.mglo</code></td><td><code>koth_team.txt</code>、<code>koth_pro.txt</code>、<code>koth_crazyking.txt</code></td></tr><tr><td><code>infection.mglo</code></td><td><code>infection_safehavens.txt</code>、<code>infection_newhavens.txt</code></td></tr><tr><td><code>slayer.mglo</code></td><td><code>slayer_team.txt</code>、<code>slayer_pro.txt</code>、<code>slayer_classic.txt</code>、<code>SWAT.txt</code></td></tr></tbody></table><p>典型的な派生スクリプトは非常に短いです。</p><div class="language-megalo vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">megalo</span><pre class="megalo-edit vp-code" tabindex="0"><code><span class="line"><span class="megalo-keyword">base</span><span class="megalo-text"> </span><span class="megalo-string">&quot;ctf.mglo&quot;</span></span>
<span class="line"><span class="megalo-keyword">include</span><span class="megalo-text"> </span><span class="megalo-string">&quot;strings/ctf_strings.txt&quot;</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-keyword">engine_data</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-parameter">name</span><span class="megalo-text"> ctf_1flag_title</span></span>
<span class="line"><span class="megalo-keyword">end</span></span>
<span class="line"><wbr></span>
<span class="line"><span class="megalo-keyword">game_options</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-modifier">lock</span><span class="megalo-text"> </span><span class="megalo-keyword">override</span><span class="megalo-text"> </span><span class="megalo-variable">teams_enabled</span><span class="megalo-text"> </span><span class="megalo-variable">true</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">override</span><span class="megalo-text"> </span><span class="megalo-variable">round_count</span><span class="megalo-text"> </span><span class="megalo-number">4</span></span>
<span class="line"><span class="megalo-text">	</span><span class="megalo-keyword">override</span><span class="megalo-text"> </span><span class="megalo-variable">score_to_win_round</span><span class="megalo-text"> </span><span class="megalo-number">1</span></span>
<span class="line"><span class="megalo-keyword">end</span></span></code></pre></div><h2 id="base-と-include" tabindex="-1">base と include <a class="header-anchor" href="#base-と-include" aria-label="Permalink to &quot;base と include&quot;">​</a></h2><p>これらは異なる 2 つの合成メカニズムです。</p><table tabindex="0"><thead><tr><th></th><th><code>base &quot;x.mglo&quot;</code></th><th><code>include &quot;x.txt&quot;</code></th></tr></thead><tbody><tr><td><strong>マージするもの</strong></td><td>コンパイル済みバリアント（バイナリ）</td><td>ソーステキスト</td></tr><tr><td><strong>ロジックを継承</strong></td><td>はい — トリガー、変数、すべて</td><td>インクルードされた要素だけ</td></tr><tr><td><strong>トリガーを追加できる</strong></td><td>いいえ</td><td>はい</td></tr><tr><td><strong>典型的な用途</strong></td><td>バリアントファミリー（CTF から 1-Flag CTF）</td><td>共有文字列、ロードアウト、共通ロジック</td></tr></tbody></table><p>両方を使うこともできます — 派生スクリプトがコンパイル済み親を <code>base</code> し、追加の文字列テーブルやヘルパーロジックを <code>include</code> する、など。</p><h2 id="関連項目" tabindex="-1">関連項目 <a class="header-anchor" href="#関連項目" aria-label="Permalink to &quot;関連項目&quot;">​</a></h2><ul><li><a href="/MegaloEvolved/beta/docs/ja/language/syntax">構文とファイル形式</a> — include、ファイル構造、<a href="/MegaloEvolved/beta/docs/ja/language/syntax#the-element-model">要素モデル</a></li><li><a href="/MegaloEvolved/beta/docs/ja/language/examples">サンプルスクリプト</a> — <code>base</code> 行なしの完全スクリプト</li></ul>`,24))])}const f=n(i,[["render",g]]);export{v as __pageData,f as default};
